UPDATE t_oa_enterprise
SET deleted = #{deletedFlag, jdbcType=SMALLINT, typeHandler=net.lab1024.sa.common.mybatis.typehandler.BooleanToSmallintTypeHandler}
WHERE enterprise_id = #{enterpriseId}

mapper.select:
SELECT *
FROM t_oa_enterprise
WHERE enterprise_name = #{enterpriseName}
AND deleted = #{deletedFlag, jdbcType=SMALLINT, typeHandler=net.lab1024.sa.common.mybatis.typehandler.BooleanToSmallintTypeHandler}

    AND enterprise_id != #{excludeEnterpriseId}

SELECT t_oa_enterprise.*
FROM t_oa_enterprise

    deleted = #{queryForm.deletedFlag, jdbcType=SMALLINT, typeHandler=net.lab1024.sa.common.mybatis.typehandler.BooleanToSmallintTypeHandler}

        AND (enterprise_name ILIKE CONCAT('%', #{queryForm.keywords}, '%') OR contact ILIKE CONCAT('%', #{queryForm.keywords}, '%') OR
        contact_phone ILIKE CONCAT('%', #{queryForm.keywords}, '%') OR create_user_name ILIKE CONCAT('%', #{queryForm.keywords}, '%'))


        AND TO_CHAR(create_time, 'YYYY-MM-DD') >= #{queryForm.startTime}


        AND TO_CHAR(create_time, 'YYYY-MM-DD') <= #{queryForm.endTime}


        AND disabled = #{queryForm.disabledFlag, jdbcType=SMALLINT, typeHandler=net.lab1024.sa.common.mybatis.typehandler.BooleanToSmallintTypeHandler}



    ORDER BY create_time DESC

SELECT t_oa_enterprise.*
FROM t_oa_enterprise

    deleted = #{queryForm.deletedFlag, jdbcType=SMALLINT, typeHandler=net.lab1024.sa.common.mybatis.typehandler.BooleanToSmallintTypeHandler}

        AND (enterprise_name ILIKE CONCAT('%', #{queryForm.keywords}, '%') OR contact ILIKE CONCAT('%', #{queryForm.keywords}, '%') OR
        contact_phone ILIKE CONCAT('%', #{queryForm.keywords}, '%') OR create_user_name ILIKE CONCAT('%', #{queryForm.keywords}, '%'))


        AND TO_CHAR(create_time, 'YYYY-MM-DD') >= #{queryForm.startTime}


        AND TO_CHAR(create_time, 'YYYY-MM-DD') <= #{queryForm.endTime}


        AND disabled = #{queryForm.disabledFlag, jdbcType=SMALLINT, typeHandler=net.lab1024.sa.common.mybatis.typehandler.BooleanToSmallintTypeHandler}



    ORDER BY create_time DESC

SELECT enterprise_id, enterprise_name
FROM t_oa_enterprise
WHERE disabled = #{disabledFlag, jdbcType=SMALLINT, typeHandler=net.lab1024.sa.common.mybatis.typehandler.BooleanToSmallintTypeHandler}
AND deleted = #{deletedFlag, jdbcType=SMALLINT, typeHandler=net.lab1024.sa.common.mybatis.typehandler.BooleanToSmallintTypeHandler}

    AND type = #{type}

SELECT oe.*
FROM t_oa_enterprise oe
WHERE oe.enterprise_id = #{enterpriseId} AND oe.deleted = #{deletedFlag, jdbcType=SMALLINT, typeHandler=net.lab1024.sa.common.mybatis.typehandler.BooleanToSmallintTypeHandler}
